import{_ as t,o as a,a as o,a2 as i}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"theme-development/getting-started.md","filePath":"theme-development/getting-started.md","lastUpdated":1789464754000}'),d={name:"theme-development/getting-started.md"};function r(s,e,h,n,l,c){return a(),o("div",null,e[0]||(e[0]=[i('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>A Bagisto theme replaces the Blade views and the compiled CSS and JavaScript that the <code>Shop</code> package renders for the storefront, or that the <code>Admin</code> package renders for the admin. It never edits those packages: Bagisto looks at the theme&#39;s files <strong>before</strong> the package&#39;s own. This section takes you from a first theme folder to a theme package with its own build.</p><h2 id="what-you-ll-build" tabindex="-1">What You&#39;ll Build <a class="header-anchor" href="#what-you-ll-build" aria-label="Permalink to &quot;What You&#39;ll Build&quot;">​</a></h2><ul><li>A storefront theme with the code <code>custom-theme</code>, registered in <code>config/themes.php</code>, that overrides the home page.</li><li>The same theme as the <code>Webkul\\CustomTheme</code> package, so it can be versioned and installed on other stores.</li><li>Its own Tailwind CSS 4 and Vite build.</li><li>Section types and image templates of its own, themed emails and validation rules.</li><li>An admin theme, using the same mechanism.</li></ul><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Where</th><th>What it does</th></tr></thead><tbody><tr><td>Theme registry</td><td><code>config/themes.php</code></td><td>Lists storefront themes under <code>shop</code> and admin themes under <code>admin</code>, each with its <code>views_path</code>, its <code>vite</code> build and, for storefront themes, a <code>customize</code> block</td></tr><tr><td>Active theme</td><td>The channel&#39;s <code>theme</code> column; <code>admin-default</code> for the admin</td><td><code>Webkul\\Shop\\Http\\Middleware\\Theme</code> activates the channel&#39;s theme on every storefront request, falling back to <code>shop-default</code></td></tr><tr><td>View finder</td><td><code>packages/Webkul/Theme/src/ThemeViewFinder.php</code></td><td>Looks for a view in the active theme&#39;s <code>views_path</code> before the package that owns it</td></tr><tr><td>Theme manager and helpers</td><td><code>packages/Webkul/Theme/src/Themes.php</code> (<code>themes()</code>), <code>packages/Webkul/Theme/src/Http/helpers.php</code></td><td>Hold the active theme and load its build through <code>@bagistoVite</code> and <code>bagisto_asset()</code></td></tr><tr><td>Package views</td><td><code>packages/Webkul/Shop/src/Resources/views</code>, <code>packages/Webkul/Admin/src/Resources/views</code></td><td>The defaults a theme overrides. Never edit them: the change is lost on the next update</td></tr></tbody></table><p>A <strong>theme folder</strong> (<code>resources/themes/custom-theme/views</code>) needs no PHP. A <strong>theme package</strong> (<code>packages/Webkul/CustomTheme</code>) ships the same views plus the theme&#39;s build, section types and image templates. Choosing which theme a channel runs is a merchant task; see <a href="https://docs.bagisto.com/appearance/themes#activate-a-theme" target="_blank" rel="noreferrer">Activate a theme</a> in the User Guide.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A Bagisto 2.5 <a href="./../getting-started/installation.html">Installation</a> where you can run <code>php artisan</code> and edit <code>config/themes.php</code>.</li><li>Composer, from the theme package page on, and Node.js with npm, from the Vite page on.</li><li>Working knowledge of Blade and Laravel service providers. Vue 3 is used inline in Blade components; you don&#39;t compile <code>.vue</code> files.</li></ul><h2 id="the-path" tabindex="-1">The Path <a class="header-anchor" href="#the-path" aria-label="Permalink to &quot;The Path&quot;">​</a></h2><ol><li><a href="./creating-store-theme.html">Creating a Store Theme</a>: register a theme, override a view, and learn how views are resolved.</li><li><a href="./creating-custom-theme-package.html">Creating a Custom Theme Package</a>: move the theme into a package.</li><li><a href="./vite-powered-theme-assets.html">Vite-Powered Theme Assets</a>: give the package its own Tailwind CSS 4 and Vite build.</li><li><a href="./understanding-layouts.html">Understanding Layouts</a>: use and override the storefront and admin layouts.</li><li><a href="./blade-components.html">Blade Components</a>: the ready-made components pages are built from.</li><li><a href="./theme-sections.html">Theme Sections</a>: the section types the merchant can place on the home page.</li><li><a href="./image-cache-templates.html">Image Cache</a>: the image sizes the storefront serves, and theme overrides.</li><li><a href="./email-template.html">Email Template</a>: branded order and account emails.</li><li><a href="./validation.html">Validation</a>: browser and server validation for the forms a theme renders.</li><li><a href="./creating-admin-theme.html">Creating an Admin Theme</a>: the same mechanism for the admin.</li></ol><p>Along the way, the <a href="./../tools/blade-tracer.html">Blade Tracer</a> tool shows which Blade file renders any part of a page.</p><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Start by registering a theme and overriding one view.</p><p><strong>Continue to:</strong> <a href="./creating-store-theme.html">Creating a Store Theme</a></p>',15)]))}const g=t(d,[["render",r]]);export{p as __pageData,g as default};
